D[2659]={"^|cFF66DDFFLevel 10 Passive|r\nTeaches you |cffffffffBuild: Mechsuit|r%.\n\nYou can now generate |cffc7c7c7Scrap|r to build your |cFFFFFFFFMechsuit|r and |cffffffffScrap Shot|r and |cffffffffSticky Bomb|r now generate |cffc7c7c7Scrap|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nEnsina |cffffffffConstruir: Traje Mecânico|r.\n\nAgora pode gerar |cffc7c7c7Sucata|r para construir seu |cFFFFFFFFTraje Mecânico|r e |cffffffffDisparo de Sucata|r e |cffffffffBomba Adesiva|r agora geram |cffc7c7c7Sucata|r."}
D[3656]={"^Casting |cffffffffNanobot Reconstruction|r now applies |cffffffffPortable Potion Pack|r, healing for (.-) maximum Health every (.-)sec for (.-)%. \n\nCan only occur every 15 sec%.%s*$","Lançar |cffffffffReconstrução por Nanobôs|r agora aplica |cffffffffMaleta portátil de poções|r, curando até {{1}} vida máxima a cada {{2}} s durante {{3}}.\n\nSó pode acontecer uma vez a cada 15 s."}
D[3657]={"^|cffffffffNanobots|r now increase the targets movement speed by (.-)%% for (.-)%. \n\nCan only occur once every 10 sec%.%s*$","|cffffffffNanobôs|r agora aumentam em {{1}}% a velocidade de movimento do alvo durante {{2}}.\n\nSó pode ocorrer uma vez a cada 10 s."}
D[3658]={"^Increases the healing of your |cffffffffNanobot Reconstruction|r by (.-)%%%.%s*$","Aumenta a cura de seu |cffffffffReconstrução por Nanobôs|r em {{1}}%."}
D[3659]={"^Reduces the cost of |cffffffffNanobot Reconstruction|r by (.-)%% and increases its healing by (.-)%%%.%s*$","Reduz o custo de |cffffffffReconstrução por Nanobôs|r em {{1}}% e aumenta sua cura em {{2}}%."}
D[3660]={"^Reduces cost of |cffffffffNanobot Deconstruction|r by (.-)%% and increases damage by (.-)%%%.%s*$","Reduz o custo de |cffffffffDesconstrução Nanobótica|r em {{1}}% e aumenta seu dano em {{2}}%."}
D[3663]={"^Increases the damage of |cffffffffLightning Conductor|r by (.-)%% and allows it to stack (.-) additional times%.%s*$","Aumenta o dano de |cffffffffCondutor de Relâmpagos|r em {{1}}% e permite que se acumule {{2}} vezes adicionais."}
D[3664]={"^Increases the critical strike chance of |cffffffffThrow Dynamite|r by (.-)%% and reduces its cooldown by (.-) sec%.%s*$","Aumenta a chance de acerto crítico de |cffffffffLançar dinamite|r em {{1}}% e reduz sua recarga a {{2}} s."}
D[3665]={"^Causes |cffffffffBomb Launcher|r shots to reduce the cast time of your next |cffffffffRocket Launcher|r by (.-)%% for (.-), stacks up to 3 times%.%s*$","Faz com que os disparos do |cffffffffBomb Launcher|r reduzam o tempo de lançamento de seu próximo |cffffffffLança-Foguetes|r em {{1}}% durante {{2}}, acumula até 3 vezes."}
D[3956]={"^Removes the cooldown of |cffffffffReload|r%.%s*$","Remove a recarga de |cffffffffRecarregar|r."}
