T[228]={"^|cffffffffNanobot Barrier|r increases movement speed by (.-)%% and grants |cffffffffCyborg Speed|r, increasing movement speed by (.-)%% for (.-)%. \n\nCan only occur once every 10 sec%.%s*$","|cffffffffBarreira de Nanobôs|r aumenta a velocidade de movimento em {{1}}% e concede |cffffffffVelocidade Ciborgue|r, aumentando a velocidade de movimento em {{2}}% por {{3}}.\n\nSó pode ocorrer uma vez a cada 10 segundos."}
T[229]={"^Reduces cost of |cffffffffNanobot Deconstruction|r by (.-)%% and increases damage by (.-)%%%.%s*$","Reduz o custo de |cffffffffDesconstrução Nanobótica|r em {{1}}% e aumenta seu dano em {{2}}%."}
T[315]={"^Increases the range of |cffffffffShotgun|r by (.-) yds and teaches |cffffffffBuild: Clockwork Knight|r%.%s*$","Aumenta em {{1}} m o alcance de |cffffffffEspingarda|r e ensina |cffffffffConstruir: Cavaleiro Mecânico|r."}
T[317]={"^At the end of the duration this target will explode, dealing (.-) Fire damage to them and other enemies around them%.%s*$","Ao final da duração, o alvo explode, causando {{1}} de dano de Fogo a ele e aos inimigos próximos."}
T[318]={"^Fire Resistance Reduced%.%s*$","Resistência ao Fogo reduzida."}
T[319]={"^Taking (.-) Fire damage every (.-) sec%.%s*$","Sofre {{1}} de dano de Fogo a cada {{2}} segundos."}
T[435]={"^Nanobots are periodically unleashing a Nanobot Swarm%.%s*$","Os Nanobôs liberam periodicamente um Enxame de Nanobôs."}
T[436]={"^(.-) Arcane damage every second%.%s*$","{{1}} de dano Arcano a cada segundo."}
T[437]={"^Healing for (.-) every sec%.%s*$","Cura de {{1}} a a cada segundo."}
T[438]={"^Damage Dealt increased by (.-)%%%. Healing for (.-) every (.-) sec%. Cooldowns reduced by (.-)%%%.%s*$","O dano causado aumenta em {{1}}%. Cura {{2}} a cada {{3}} s. A recarga é reduzido em {{4}}%."}
T[455]={"^|cffffffffConsumes 15 Scrap|r\nCommands your Clockwork Knight to strike enemies within (.-)yd for (.-) Physical Damage, scaling with Agility%.%s*$","|cffffffffConsome 15 de Sucata|r\nOrdena que seu Cavaleiro Mecânico golpeie inimigos em um raio de {{1}} m, causando {{2}} de dano Físico com escalonamento de Agilidade."}
T[482]={"^Increases critical strike chance by (.-)%%%.%s*$","Aumenta a chance de acerto crítico em {{1}}%."}
T[505]={"^Increases the healing of |cffffffffRepair Shot|r by (.-)%%%.%s*$","Aumenta a cura de |cffffffffTiro de Reparo|r em {{1}}%."}
T[514]={"^Increases the duration of |cFFFFFFFFBlackpowder Barrage|r by (.-) sec and causes it to deal 25%% additional Fire damage over (.-)%.%s*$","Aumenta a duração de |cFFFFFFFFBarragem de Pólvora Negra|r em {{1}} s e faz com que inflija 25% de Dano adicional de Fogo durante {{2}}."}
T[549]={"^Increases the damage of |cffffffffGunsling|r and |cffffffffHandcannon|r against enemies affected by |cffffffffSticky Bomb|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffGunsling|r e |cffffffffHandcannon|r contra inimigos afetados por |cffffffffBomba Adesiva|r em {{1}}%."}
T[550]={"^Your Sticky Bomb ability now has a (.-)%% increased cooldown and deals (.-)%% reduced damage%.\n\nScrap Shot damage against enemies affected by Sticky Bomb cause the bomb to explode instantly without being consumed%.%s*$","Bomba Adesiva passa a ter {{1}}% a mais de recarga e causa {{2}}% menos dano.\n\nO dano de Disparo de Sucata contra inimigos afetados por Bomba Adesiva faz a bomba explodir imediatamente sem consumi-la."}
T[998]={"^Every 3rd |cffffffffStandard Round|r, within (.-), shoots arcs of electricity, slowing the target's movement speed by (.-)%% for (.-)%.%s*$","A cada terceira |cffffffffBala Padrão|r usada dentro de {{1}}, dispara arcos de eletricidade que reduzem em {{2}}% a velocidade de movimento do alvo durante {{3}}."}
T[1000]={"^Gives |cffffffffScrap Shot|r a 8%% chance to reset the cooldown of |cffffffffGunsling|r%.%s*$","Dá |cffffffffDisparo de Sucata|r 8% de chance de para restaurar a recarga de |cffffffffGunsling|r."}
T[1001]={"^Causes |cffffffffRepair Shot|r to heal nearby allies affected by |cffffffffNanobot Reconstruction|r for (.-)%.%s*$","Faz com que |cffffffffTiro de Reparo|r cure aliados próximos afetados por |cffffffffReconstrução por Nanobôs|r em {{1}}."}
T[1002]={"^Increases the damage of |cffffffffRifle Scrap Shots|r and |cffffffffShotgun Scrap Shots|r by (.-)%%%.%s*$","Aumenta em {{1}}% o dano de |cffffffffDisparos de Sucata do Rifle|r e |cffffffffDisparos de Sucata da Espingarda|r."}
T[1004]={"^|cffffffffSpanner Smash|r resets the cooldown of |cffffffffScrap Slam|r if used within (.-) of |cffffffffSticky Bomb|r%.%s*$","|cffffffffGolpe com chave inglesa|r reinicia a recarga de |cffffffffGolpe de Sucata|r se é usada em um raio de {{1}} de |cffffffffBomba Adesiva|r."}
