T[18945]={"^Increases the damage of |cffffffffSticky Bomb|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffBomba Adesiva|r em {{1}}%."}
T[18967]={"^|cFFFFFFFFSprocket Strike|r now increases your movement speed by (.-)%% for (.-), stacking (.-) times%.%s*$","|cFFFFFFFFGolpe da Engrenagem|r agora aumenta sua velocidade de movimento em {{1}}% durante {{2}}, acumulando até {{3}} vezes."}
