T[18984]={"^|cffffffffSticky Bomb|r now slows the target's movement speed by (.-)%% for (.-)%.%s*$","|cffffffffBomba Adesiva|r agora desacelera a velocidade de movimento do alvo em {{1}}% durante {{2}}."}
T[18986]={"^Dealing 50%% of the damage dealt by Rocket Launcher every (.-) sec%.%s*$","Absorve 50% do dano causado pelo Lança-granadas a cada {{1}} s."}
T[19239]={"^Increases the damage dealt by your Sapper Charge detonation, and your Sticky Bomb Detonation by 15%%%.Also increases all Fire damage dealt by an additional 10%%%.%s*$","Aumenta o dano causado pela detonação de Carga minadora e pela Detonação de bombas pegajosas em um 15%. Também aumenta todo o dano de Fogo que causa em mais 10%."}
T[19432]={"^Cast time of your next Repair Shot reduced by 0%.5 sec%.%s*$","O tempo de lançamento de seu próximo Reparo Disparo é reduzido em 0,5 s."}
T[22021]={"^(.-) Fire damage every (.-) sec%.%s*$","{{1}} p. de dano de Fogo a cada {{2}} s."}
T[25766]={"^Stunned by Snivel Rustrocket's portable rocket launcher%.%s*$","Atordoado pelo Lança-Foguetes portátil de Reclamão Misilóxido."}

